import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"0006 — v1alpha2 restarts Form lines without reusing v1alpha1 identities","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0006-v1alpha2-restarts-form-lines.md","filePath":"spec/decisions/0006-v1alpha2-restarts-form-lines.md"}'),o={name:"spec/decisions/0006-v1alpha2-restarts-form-lines.md"};function n(s,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_0006-—-v1alpha2-restarts-form-lines-without-reusing-v1alpha1-identities" tabindex="-1">0006 — v1alpha2 restarts Form lines without reusing v1alpha1 identities <a class="header-anchor" href="#_0006-—-v1alpha2-restarts-form-lines-without-reusing-v1alpha1-identities" aria-label="Permalink to &quot;0006 — v1alpha2 restarts Form lines without reusing v1alpha1 identities&quot;">​</a></h1><ul><li>Status: accepted; the v1alpha2 epoch it creates is retained provider-v2 preview source since <a href="./0013-v1alpha3-lane-ships-in-provider-v2-1.html">0013</a></li><li>Date: 2026-08-05</li><li>Owners: Takoform maintainers</li><li>Supersedes: the rule in <a href="./0004-takoform-is-an-experimental-specification.html">0004</a> that an existing Kind can never restart at <code>0.x</code></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Classifying the pre-reset catalog as Legacy removed its false maturity claims, but it left those historical version numbers attached to the only visible Form line. <code>EdgeWorker@4.0.0</code> therefore still looked current even though no current Experimental EdgeWorker existed. Continuing the same version line would make new design work inherit compatibility expectations from specifications that the project explicitly stopped recommending.</p><p>An exact FormRef includes <code>apiVersion</code>, Kind, definition version, and schema digest. A new API epoch can therefore reuse a useful Kind name and restart its Form SemVer without overwriting or ambiguously reassigning any published identity.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>forms.takoform.com/v1alpha1</code> is the frozen Legacy specification epoch. <code>forms.takoform.com/v1alpha2</code> is the current Specification epoch. The epoch is not itself a maturity state: each definition remains a Proposal until its own lifecycle record transitions to Experimental.</p><p>Package API versions are envelopes, not Form maturity. The already published <code>packages.forms.takoform.com/v1alpha2</code> package schema refers to a v1alpha1 FormRef and is therefore retained unchanged. Current v1alpha2 Forms use the new <code>packages.forms.takoform.com/v1alpha3</code> content-addressed package envelope. This extra package-profile increment is required by immutable public schema identity; it does not advance any Form version.</p><p>Current v1alpha2 candidates may reuse v1alpha1 Kind names. Every new v1alpha2 Form begins as an unversioned Proposal; a reproducible <code>0.1.0</code> source package may be reviewed before publication, but it becomes an Experimental Form only after the explicit lifecycle transition and public release. No v1alpha1 version number, maturity label, package locator, provider mapping, or admission result is inherited by the v1alpha2 Form.</p><p>The v1alpha2 Form Definition omits the v1alpha1 document-local <code>status</code> field. Proposal, Experimental, Stable, and Legacy are mutable lifecycle facts owned only by <code>forms/lifecycle.json</code>; duplicating one inside immutable Definition bytes would create a second authority that becomes stale after a transition. Published v1alpha1 Definitions retain their exact historical field and bytes.</p><p>The 34 v1alpha1 Forms are not mechanically cloned into v1alpha2. Each Kind must again establish a real workload, owner, host implementation, prior-art review, portable boundary, fixtures, migration behavior, and security analysis.</p><p>The initial design set is the nine Form-backed Resources currently implemented and offered by Takosumi Cloud: EdgeWorker, RelationalDatabase, ObjectBucket, KeyValueStore, Queue, Schedule, ContainerService, StatefulEntity, and VectorIndex. Cloud implementation provides a real consumer and first-host starting point, not maturity, portability, or publication authority. Cloud&#39;s VerifiedDomain and AIGateway remain separate non-Form services. Absence from v1alpha2 remains the default for every other former Kind.</p><p>Provider SemVer remains independent. Provider v1 is the frozen v1alpha1 compatibility client. Provider v2 is the v1alpha2 client and fails closed on provider-v1 state instead of pretending it is a state upgrade.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>EdgeWorker@4.0.0</code> remains an exact Legacy identity, while <code>forms.takoform.com/v1alpha2 / EdgeWorker@0.1.0</code> can become a distinct current identity after its Proposal earns publication.</li><li>current docs and provider surfaces expose only the nine Proposal-derived v1alpha2 source candidates and state that none has yet passed Experimental admission;</li><li>a v1alpha2 Definition cannot claim or cache its own maturity; readers join its exact FormRef with the lifecycle authority when they need that fact;</li><li>old provider binaries, tags, releases, Resource pins, revocations, and recovery paths remain valid and immutable;</li><li>v1alpha1 and v1alpha2 package envelopes remain readable for Legacy Forms, while current Forms use the v1alpha3 envelope;</li><li>a host may retain v1alpha1 lifecycle compatibility, but it must advertise and activate that Legacy lane explicitly;</li><li>provider users pin v1 for Legacy state or migrate explicitly to provider v2.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Continue EdgeWorker at 5.0.0.</strong> Rejected because it represents the reset as another compatibility change inside the specification line being retired.</li><li><strong>Publish EdgeWorker@0.1.0 in v1alpha1.</strong> Rejected because SemVer resolution and human readers would see two conflicting starts in one API epoch.</li><li><strong>Rename EdgeWorker.</strong> Rejected because the portable concept remains useful; the API epoch already provides the identity boundary.</li><li><strong>Republish all 34 Forms at 0.1.0.</strong> Rejected because it repeats premature standardization with smaller numbers.</li></ul>',17)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
